(async () => {
  const photos = {
    photo2: "",
    photo3: "",
    photo4: "",
    photo5: ""
  };
  function base64ToBlob(base64, mime) {
    const byteCharacters = atob(base64);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
      byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    return new Blob([byteArray], { type: mime });
  }
  const input = document.querySelector('input[type="file"]');
  const dataTransfer = new DataTransfer();
  dataTransfer.items.add(new File([base64ToBlob(photos.photo2, 'image/jpeg')], 'photo2.jpg', { type: 'image/jpeg' }));
  dataTransfer.items.add(new File([base64ToBlob(photos.photo3, 'image/jpeg')], 'photo3.jpg', { type: 'image/jpeg' }));
  dataTransfer.items.add(new File([base64ToBlob(photos.photo4, 'image/png')], 'photo4.png', { type: 'image/png' }));
  dataTransfer.items.add(new File([base64ToBlob(photos.photo5, 'image/png')], 'photo5.png', { type: 'image/png' }));
  input.files = dataTransfer.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return 'Upload triggered';
})()
